/**
 * Session rows for the cookie-based auth: create, look up by token hash, revoke.
 */
import { eq, lt } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, sessions, users } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { brandId, brandStamp } from "./_mappers";
import type {
  IsoTimestamp,
  OrgId,
  SessionId,
  UserId,
} from "@/types/common";
import type { SessionPrincipal } from "@/types/member";

/**
 * Sessions are global rather than tenant-scoped: one cookie can move between
 * organizations via `activeOrgId`, and `SessionService` resolves the `Actor`
 * for whichever org the request addresses.
 */
export async function createSession(
  userId: UserId,
  tokenHash: string,
  expiresAt: IsoTimestamp,
): Promise<SessionPrincipal> {
  const stamp = toIsoTimestamp(new Date());
  const user = getDb().select().from(users).where(eq(users.id, userId)).get();
  if (!user) throw new Error(`User ${userId} not found`);

  getDb()
    .insert(sessions)
    .values({
      id: newId(),
      userId,
      activeOrgId: null,
      tokenHash,
      expiresAt,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .run();

  return {
    userId,
    email: user.email,
    activeOrgId: null,
    expiresAt,
  };
}

/** Expired rows resolve to `null` rather than being returned and re-checked. */
export async function findSessionByTokenHash(
  tokenHash: string,
): Promise<SessionPrincipal | null> {
  const row = getDb()
    .select({ session: sessions, user: users })
    .from(sessions)
    .innerJoin(users, eq(users.id, sessions.userId))
    .where(eq(sessions.tokenHash, tokenHash))
    .get();

  if (!row) return null;
  if (row.session.expiresAt <= new Date().toISOString()) return null;

  return {
    userId: brandId<UserId>(row.session.userId),
    email: row.user.email,
    activeOrgId:
      row.session.activeOrgId === null
        ? null
        : brandId<OrgId>(row.session.activeOrgId),
    expiresAt: brandStamp(row.session.expiresAt),
  };
}

export async function setActiveOrg(
  sessionId: SessionId,
  orgId: OrgId,
): Promise<void> {
  getDb()
    .update(sessions)
    .set({ activeOrgId: orgId, updatedAt: toIsoTimestamp(new Date()) })
    .where(eq(sessions.id, sessionId))
    .run();
}

export async function revokeSession(sessionId: SessionId): Promise<void> {
  getDb().delete(sessions).where(eq(sessions.id, sessionId)).run();
}

/** Housekeeping sweep; returns how many rows the scheduler removed. */
export async function purgeExpiredSessions(
  now: IsoTimestamp,
): Promise<number> {
  const rows = getDb()
    .delete(sessions)
    .where(lt(sessions.expiresAt, now))
    .returning({ id: sessions.id })
    .all();
  return rows.length;
}

import { index, integer, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import { idColumn, softDeleteColumns, timestampColumns } from "./_shared";

export const organizations = sqliteTable(
  "organizations",
  {
    id: idColumn(),
    name: text("name").notNull(),
    slug: text("slug").notNull(),
    ownerId: text("owner_id").notNull(),
    plan: text("plan", {
      enum: ["free", "starter", "growth", "enterprise"],
    })
      .notNull()
      .default("free"),
    logoUrl: text("logo_url"),
    trialEndsAt: text("trial_ends_at"),
    defaultIssueStatus: text("default_issue_status").notNull().default("backlog"),
    allowPublicProjects: integer("allow_public_projects", { mode: "boolean" })
      .notNull()
      .default(false),
    requireTwoFactor: integer("require_two_factor", { mode: "boolean" })
      .notNull()
      .default(false),
    digestHourUtc: integer("digest_hour_utc").notNull().default(7),
    enabledFlagOverrides: text("enabled_flag_overrides").notNull().default("[]"),
    ...timestampColumns,
    ...softDeleteColumns,
  },
  (table) => [
    uniqueIndex("organizations_slug_idx").on(table.slug),
    index("organizations_owner_idx").on(table.ownerId),
  ],
);

export const organizationUsage = sqliteTable("organization_usage", {
  orgId: text("org_id").primaryKey(),
  seatsUsed: integer("seats_used").notNull().default(0),
  projectsUsed: integer("projects_used").notNull().default(0),
  issuesUsed: integer("issues_used").notNull().default(0),
  storageMbUsed: integer("storage_mb_used").notNull().default(0),
  measuredAt: text("measured_at").notNull(),
});

export type OrganizationRow = typeof organizations.$inferSelect;
export type NewOrganizationRow = typeof organizations.$inferInsert;
export type OrganizationUsageRow = typeof organizationUsage.$inferSelect;

