/**
 * Changes the workspace's URL slug (ADR 0005). The slug is taken as typed and
 * never suffixed: one another workspace uses or holds is refused with the same
 * invalid-slug error a malformed slug gets. The old slug keeps resolving to this
 * workspace for `ORG_SLUG_HOLD_DAYS`. Renaming to the current slug changes
 * nothing and publishes nothing.
 */
export async function renameOrganizationSlug(
  actor: Actor,
  input: RenameOrganizationSlugInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));
  assertValidSlug(input.slug);

  const current = await orgRepo.findOrgById(input.orgId);
  if (current === null || isArchived(current)) {
    throw new NotFoundError("Organization", input.orgId);
  }
  if (current.slug === input.slug) return current;

  const renamed = await orgRepo.renameOrgSlug(
    input.orgId,
    current.slug,
    input.slug,
  );
  if (renamed === null) {
    throw new InvalidSlugError(input.slug, "is not available");
  }

  await emit("organization.slug_changed", {
    ...actorEnvelope(actor),
    from: current.slug,
    to: renamed.slug,
  });

  return renamed;
}

