/**
 * Renaming a workspace URL slug (ADR 0005): the new slug is the current one, the
 * old one keeps resolving for `ORG_SLUG_HOLD_DAYS`, refusals change nothing, and
 * a rename publishes one event and records one audit row.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { ORG_SLUG_HOLD_DAYS } from "@/config/constants";
import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { InvalidSlugError } from "@/lib/slug";
import * as orgRepo from "@/server/repositories/organization-repository";
import {
  listActivity,
  registerActivityListeners,
} from "@/server/services/activity-service";
import {
  createOrganization,
  listOrganizationsForUser,
  renameOrganizationSlug,
  resolveOrgBySlug,
} from "@/server/services/organization-service";
import { resolveActorForOrg } from "@/server/services/session-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { TaskflowEventMap, Unsubscribe } from "@/types/event";
import type { SessionPrincipal } from "@/types/member";

const DAY_MS = 24 * 60 * 60 * 1000;

let cleanup: () => void;
let detachActivity: Unsubscribe;
let detachCapture: Unsubscribe;
const published: TaskflowEventMap["organization.slug_changed"][] = [];

function principalFor(tenant: Tenant): SessionPrincipal {
  return {
    userId: tenant.userIds.owner,
    email: "owner@example.test",
    activeOrgId: tenant.org.id,
    expiresAt: toIsoTimestamp(new Date(Date.now() + DAY_MS)),
  };
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachActivity = registerActivityListeners();
  detachCapture = subscribe("organization.slug_changed", (payload) => {
    published.push(payload);
  });
});

afterAll(() => {
  detachCapture();
  detachActivity();
  cleanup();
});

describe("renameOrganizationSlug", () => {
  it("makes the new slug current and keeps the old one resolving", async () => {
    const tenant = await createTenant("alpha");
    const before = await orgRepo.findOrgById(tenant.org.id);

    const renamed = await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "alpha-labs",
    });

    expect(renamed).toMatchObject({
      id: tenant.org.id,
      slug: "alpha-labs",
      name: before?.name,
      plan: before?.plan,
    });
    expect((await orgRepo.findOrgById(tenant.org.id))?.slug).toBe("alpha-labs");
    expect((await resolveOrgBySlug("alpha-labs"))?.id).toBe(tenant.org.id);
    expect((await resolveOrgBySlug("alpha"))?.id).toBe(tenant.org.id);
    expect((await resolveActorForOrg(principalFor(tenant), "alpha"))?.orgId).toBe(
      tenant.org.id,
    );

    const listed = await listOrganizationsForUser(tenant.userIds.owner);
    expect(listed.map((org) => org.slug)).toEqual(["alpha-labs"]);
  });

  it("holds the old slug for ORG_SLUG_HOLD_DAYS, then releases it", async () => {
    const tenant = await createTenant("bravo");
    const start = new Date();

    vi.useFakeTimers({ toFake: ["Date"] });
    try {
      vi.setSystemTime(start);
      await renameOrganizationSlug(tenant.actors.owner, {
        orgId: tenant.org.id,
        slug: "bravo-labs",
      });

      const releasedAt = start.getTime() + ORG_SLUG_HOLD_DAYS * DAY_MS;

      vi.setSystemTime(releasedAt - 1);
      expect((await resolveOrgBySlug("bravo"))?.id).toBe(tenant.org.id);

      vi.setSystemTime(releasedAt);
      expect(await resolveOrgBySlug("bravo")).toBeNull();
