    await rename("hotel-three");
    await rename("hotel");

    expect((await orgRepo.findOrgById(hotel.org.id))?.slug).toBe("hotel");
    expect((await resolveOrgBySlug("hotel-two"))?.id).toBe(hotel.org.id);
    expect((await resolveOrgBySlug("hotel-three"))?.id).toBe(hotel.org.id);

    const india = await createTenant("india");
    await expect(
      renameOrganizationSlug(india.actors.owner, {
        orgId: india.org.id,
        slug: "hotel-two",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);
  });

  it("releases each retired slug on its own schedule", async () => {
    const juliet = await createTenant("juliet");
    const start = new Date();

    vi.useFakeTimers({ toFake: ["Date"] });
    try {
      vi.setSystemTime(start);
      await renameOrganizationSlug(juliet.actors.owner, {
        orgId: juliet.org.id,
        slug: "juliet-two",
      });

      vi.setSystemTime(start.getTime() + 20 * DAY_MS);
      await renameOrganizationSlug(juliet.actors.owner, {
        orgId: juliet.org.id,
        slug: "juliet-three",
      });

      vi.setSystemTime(start.getTime() + ORG_SLUG_HOLD_DAYS * DAY_MS);
      expect(await resolveOrgBySlug("juliet")).toBeNull();
      expect((await resolveOrgBySlug("juliet-two"))?.id).toBe(juliet.org.id);

      vi.setSystemTime(start.getTime() + (20 + ORG_SLUG_HOLD_DAYS) * DAY_MS);
      expect(await resolveOrgBySlug("juliet-two")).toBeNull();
      expect((await resolveOrgBySlug("juliet-three"))?.id).toBe(juliet.org.id);
    } finally {
      vi.useRealTimers();
    }
  });

  it("refuses a member, and a malformed slug, changing nothing", async () => {
    const kilo = await createTenant("kilo");

    await expect(
      renameOrganizationSlug(kilo.actors.member, {
        orgId: kilo.org.id,
        slug: "kilo-two",
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      renameOrganizationSlug(kilo.actors.owner, {
        orgId: kilo.org.id,
        slug: "settings",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);

    await expect(
      renameOrganizationSlug(kilo.actors.owner, {
        orgId: kilo.org.id,
        slug: "Kilo Two",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);

    expect((await orgRepo.findOrgById(kilo.org.id))?.slug).toBe("kilo");
  });

  it("publishes one event and records one audit row, on behalf of the renamer", async () => {
    const lima = await createTenant("lima");
    const publishedBefore = published.length;

    await renameOrganizationSlug(lima.actors.admin, {
      orgId: lima.org.id,
      slug: "lima-two",
    });

    expect(published.slice(publishedBefore)).toEqual([
      expect.objectContaining({
        orgId: lima.org.id,
        actorId: lima.userIds.admin,
        from: "lima",
        to: "lima-two",
      }),
    ]);

    const page = await listActivity(lima.actors.owner, {
      orgId: lima.org.id,
      action: ["organization.slug_changed"],
      limit: 25,
      cursor: null,
    });
    expect(page.items).toHaveLength(1);
    expect(page.items[0]).toMatchObject({
      action: "organization.slug_changed",
      actorId: lima.userIds.admin,
      subjectKind: "organization",
      subjectId: lima.org.id,
      metadata: { from: "lima", to: "lima-two" },
    });
  });

  it("changes nothing and publishes nothing when renaming to the current slug", async () => {
    const mike = await createTenant("mike");
    const publishedBefore = published.length;
    const before = await orgRepo.findOrgById(mike.org.id);

    const result = await renameOrganizationSlug(mike.actors.owner, {
      orgId: mike.org.id,
      slug: "mike",
    });

    expect(result).toEqual(before);
    expect(await orgRepo.findOrgById(mike.org.id)).toEqual(before);
    expect(published).toHaveLength(publishedBefore);

    const page = await listActivity(mike.actors.owner, {
      orgId: mike.org.id,
      action: ["organization.slug_changed"],
      limit: 25,
      cursor: null,
    });
    expect(page.total).toBe(0);
  });

  it("stops resolving a deleted workspace's slugs, and refuses to rename it", async () => {
    const november = await createTenant("november");
    await renameOrganizationSlug(november.actors.owner, {
      orgId: november.org.id,
      slug: "november-two",
    });

    await orgRepo.archiveOrg(november.org.id);

    expect(await resolveOrgBySlug("november-two")).toBeNull();
    expect(await resolveOrgBySlug("november")).toBeNull();
    await expect(
      renameOrganizationSlug(november.actors.owner, {
        orgId: november.org.id,
        slug: "november-three",
      }),
    ).rejects.toMatchObject({ code: "not_found" });
  });
});

